     8→function store(path, credentials) {
     9→  const auth = encodedAuthString(credentials.username, credentials.token);
    10→
    11→  let kpmrc;
    12→  try {
    13→    const contents = fs.readFileSync(path);
    14→    kpmrc = contents ? JSON.parse(contents) : {};
    15→  } catch (err) {
    16→    kpmrc = {};
    17→  }
    18→
    19→  kpmrc.auth = auth;
    20→
    21→  return fs.writeFileSync(path, JSON.stringify(kpmrc, null, 2) + EOL);
    22→}
    23→
    24→function retrieve(path) {
    25→  try {
    26→    const contents = fs.readFileSync(path);
    27→    const parsed = JSON.parse(contents);
    28→    return parsed ? parsed.auth : null;
    29→  } catch (err) {
    30→    return null;
    31→  }
    32→}
    33→
    34→function encodedAuthString(username, token) {
    35→  const auth = authString(username, token);
    36→  return new Buffer(auth, 'utf8').toString('base64')
    37→}
    38→
    39→function authString(username, token) {
    40→  return `${username}:${token}`;
    41→}
    42→
    43→module.exports = {
    44→  retrieve,
    45→  store: curry(store)
    46→};
